class Solution:
    def isValidBST(self, root) -> bool:
        def valid(r, lo, hi):
            if not r:
                return True
            if not (lo < r.val < hi):
                return False
            return valid(r.left, lo, r.val) and valid(r.right, r.val, hi)
        return valid(root, float('-inf'), float('inf'))

class Solution {
    unordered_map<int,int> pos; int idx = 0; vector<int> pre;
    TreeNode* build(vector<int>& in, int lo, int hi) {
        if (lo > hi) return nullptr;
        int rootVal = pre[idx++];
        TreeNode* root = new TreeNode(rootVal);
        int mid = pos[rootVal];
        root->left = build(in, lo, mid - 1);
        root->right = build(in, mid + 1, hi);
        return root;
    }
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        pre = preorder;
        for (int i = 0; i < (int)inorder.size(); i++) pos[inorder[i]] = i;
        return build(inorder, 0, inorder.size() - 1);
    }
};

class Solution:
    def buildTree(self, preorder, inorder):
        pos = {v: i for i, v in enumerate(inorder)}
        self.idx = 0
        def build(lo, hi):
            if lo > hi:
                return None
            val = preorder[self.idx]
            self.idx += 1
            root = TreeNode(val)
            mid = pos[val]
            root.left = build(lo, mid - 1)
            root.right = build(mid + 1, hi)
            return root
        return build(0, len(inorder) - 1)

class Solution {
public:
    vector<int> rightSideView(TreeNode* root) {
        vector<int> res; if (!root) return res;
        queue<TreeNode*> q; q.push(root);
        while (!q.empty()) {
            int sz = q.size();
            for (int i = 0; i < sz; i++) {
                TreeNode* n = q.front(); q.pop();
                if (i == sz - 1) res.push_back(n->val);
                if (n->left) q.push(n->left);
                if (n->right) q.push(n->right);
            }
        }
        return res;
    }
};

from collections import deque
class Solution:
    def rightSideView(self, root) -> list[int]:
        if not root:
            return []
        res, q = [], deque([root])
        while q:
            sz = len(q)
            for i in range(sz):
                n = q.popleft()
                if i == sz - 1:
                    res.append(n.val)
                if n.left: q.append(n.left)
                if n.right: q.append(n.right)
        return res
